// Year 3 science and the world: plants, nutrition, skeletons and muscles, rocks and soils,
// light and reflection, forces and magnets, working scientifically; countries of Europe,
// UK cities, rivers and mountains, volcanoes and earthquakes, compass and grid references,
// climate zones; Year 4 tasters (states of matter, the water cycle, digestion and teeth,
// classification keys, circuits).

const fact = (id, topic, prompt, answer, distractors, explain, extra = {}) => ({ id: `science.y3.${id}`, topic: `science.y3-${topic}`, kind: 'fact', prompt, answer, distractors, explain, ...extra });
const mcq = (id, topic, prompt, options, explain, extra = {}) => ({ id: `science.y3.${id}`, topic: `science.y3-${topic}`, kind: 'mcq', prompt, options: options.map(([text, correct, feedback]) => ({ text, correct: !!correct, feedback })), explain, ...extra });
const order = (id, topic, prompt, items, explain, labels = null) => ({ id: `science.y3.${id}`, topic: `science.y3-${topic}`, kind: 'order', prompt, items, labels, explain });
const mapfact = (id, topic, map, layer, feature, answer, explain, extra = {}) => ({ id: `science.y3.${id}`, topic: `science.y3-${topic}`, kind: 'mapfact', map, layer, feature, answer, explain, ...extra });
const C = { formats: ['choice'] };

const topics = [
  { id: 'science.y3-plants', title: 'How plants work', kind: 'facts', prereqs: ['science.plants'], batch: 5, intro: 'Every part of a plant has a job. Roots drink and hold on, the stem carries water up like a pipe, leaves make food from sunlight, and flowers make seeds.', teach: 'Explain how water gets from the soil to the leaves.', talk: 'Put a white flower or a stick of celery in coloured water and watch it change colour over a day.' },
  { id: 'science.y3-seeds', title: 'Flowers, pollination and seeds', kind: 'facts', prereqs: ['science.y3-plants'], batch: 5, intro: 'Flowers are a plant’s way of making seeds. Insects carry pollen from flower to flower, seeds form, and then the seeds travel to new places to grow.', teach: 'Explain three ways seeds travel away from the parent plant.', talk: 'Blow a dandelion clock together and count how far the seeds fly.' },
  { id: 'science.y3-nutrition', title: 'Food and nutrition', kind: 'facts', prereqs: ['science.food', 'science.body'], batch: 5, intro: 'Animals cannot make their own food like plants can. We need the right mix of foods: carbohydrates for energy, protein for growing, fruit and vegetables for vitamins, and a little fat.', teach: 'Explain why a racing driver needs carbohydrates before a race.', talk: 'Look at {her} dinner plate and sort the foods into groups together.' },
  { id: 'science.y3-skeletons', title: 'Skeletons and muscles', kind: 'facts', prereqs: ['science.y3-nutrition'], batch: 5, intro: 'Your skeleton holds you up, protects your insides and helps you move. Muscles pull on bones to make them move. Some animals have no bones at all!', teach: 'Explain how muscles make your arm bend.', talk: 'Ask {him} to feel the muscle at the front of {her} arm while bending and straightening it.' },
  { id: 'science.y3-rocks', title: 'Rocks and soils', kind: 'facts', prereqs: ['science.rocks'], batch: 5, intro: 'There are three families of rock: igneous rocks made from cooled lava or magma, sedimentary rocks made from layers squashed together, and metamorphic rocks changed by heat and pressure.', teach: 'Explain how a sedimentary rock forms.', talk: 'Collect a few pebbles and test which ones soak up drops of water.' },
  { id: 'science.y3-light', title: 'Light, mirrors and shadows', kind: 'facts', prereqs: ['science.light'], batch: 5, intro: 'We see things when light bounces off them into our eyes. Shiny surfaces reflect light well. Shadows change size when the light source moves.', teach: 'Explain why your shadow gets bigger when you walk towards a torch.', talk: 'Use a torch and a toy to make a shadow, then move the torch closer and further away.' },
  { id: 'science.y3-forces', title: 'Forces, friction and magnets', kind: 'facts', prereqs: ['science.forces'], batch: 5, intro: 'Some forces need contact, like a push or friction. Magnets can push and pull without touching. Engineers think about friction all the time when they design racing cars.', teach: 'Explain why racing tyres need lots of grip but a race car’s body needs to be smooth.', talk: 'Roll a toy car down a ramp onto carpet, wood and a towel. Which surface stops it soonest?' },
  { id: 'science.y3-scientist', title: 'Thinking like a scientist', kind: 'facts', prereqs: ['science.y3-forces'], batch: 4, intro: 'Scientists ask questions, make predictions and carry out fair tests. In a fair test you change only ONE thing and keep everything else the same.', teach: 'Explain what makes a test fair.', talk: 'Plan a test together: which paper aeroplane flies furthest? What must stay the same?' },
  { id: 'science.y3-europe', title: 'Countries of Europe', kind: 'facts', prereqs: ['science.countries'], batch: 5, intro: 'Europe is the continent the UK belongs to. It has more than 40 countries, from icy Iceland in the north to sunny Greece in the south.', teach: 'Name four countries in Europe and one fact about each.', talk: 'When you see a car number plate or a football team from another country, find it on the map.' },
  { id: 'science.y3-ukplaces', title: 'UK cities, rivers and mountains', kind: 'facts', prereqs: ['science.uk', 'science.coasts'], batch: 5, intro: 'The UK has big cities, long rivers and high mountains. Ben Nevis in Scotland is the highest mountain in the whole UK.', teach: 'Name the highest mountain in each of Scotland, Wales and England.', talk: 'Find the nearest city and river to your home on the map.' },
  { id: 'science.y3-volcanoes', title: 'Volcanoes and earthquakes', kind: 'facts', prereqs: ['science.y3-rocks'], batch: 5, intro: 'The Earth’s outer layer, the crust, is cracked into giant pieces called plates. Where plates push, pull or slide past each other, we get earthquakes and volcanoes.', teach: 'Explain why there are earthquakes in some places and not others.', talk: 'Peel a satsuma and talk about how the Earth’s crust is broken into pieces like the peel.' },
  { id: 'science.y3-compass', title: 'Compass points and grid references', kind: 'facts', prereqs: ['science.maps'], batch: 5, intro: 'The 8 points of the compass are north, north-east, east, south-east, south, south-west, west and north-west. Grid references help you find a square on a map: along the corridor, then up the stairs!', teach: 'Explain how to find the square at grid reference C3.', talk: 'Draw a treasure map of the garden with a grid, and give {him} a grid reference to find the treasure.' },
  { id: 'science.y3-climate', title: 'Climate zones and biomes', kind: 'facts', prereqs: ['science.hotcold'], batch: 5, intro: 'Climate is the usual weather of a place over many years. Hot places near the Equator, cold places near the Poles, and in between, temperate places like the UK.', teach: 'Explain the difference between weather and climate.', talk: 'Ask {him} which biome {she} would like to explore, and what {she} would need to take.' },
  // Year 4 tasters
  { id: 'science.y3-states', title: 'Solids, liquids and gases', kind: 'facts', tier: 'stretch', prereqs: ['science.materials'], batch: 5, intro: 'Everything is a solid, a liquid or a gas. Heating and cooling can change one into another: ice melts into water, and water evaporates into water vapour.', teach: 'Explain the journey of a raindrop round the water cycle.', talk: 'Watch an ice cube melt on a plate, then talk about where puddles go on a sunny day.' },
  { id: 'science.y3-digestion', title: 'Teeth and digestion', kind: 'facts', tier: 'stretch', prereqs: ['science.y3-nutrition'], batch: 5, intro: 'Digestion breaks food into tiny pieces your body can use. It starts with your teeth and ends a long way later, after a journey through your stomach and intestines.', teach: 'Explain the job of each type of tooth.', talk: 'Look in a mirror together and find {her} incisors, canines and molars.' },
  { id: 'science.y3-keys', title: 'Sorting living things with keys', kind: 'facts', tier: 'stretch', prereqs: ['science.y3-skeletons', 'science.minibeasts'], batch: 5, intro: 'Scientists sort living things into groups. A classification key asks yes-or-no questions, one at a time, until only one answer is left.', teach: 'Explain how a key helps you name an animal you don’t know.', talk: 'Make a yes/no key together for four toys or four family members.' },
  { id: 'science.y3-circuits', title: 'Circuits and switches', kind: 'facts', tier: 'stretch', prereqs: ['science.electricity'], batch: 5, intro: 'A circuit is a complete loop. Add more batteries and a bulb gets brighter; add more bulbs and each one gets dimmer. Conductors let electricity through; insulators don’t.', teach: 'Explain why a bulb doesn’t light if there is a gap in the circuit.', talk: 'Count the switches in your kitchen. What does each one complete?' },
];

