const items = [
  // --- how plants work
  fact('pl.roots', 'plants', 'Which part of a plant takes in water from the soil and holds it in place?', 'the roots', ['the leaves', 'the flower', 'the petals'], 'Roots spread out underground to take in water and minerals, and anchor the plant.', { accept: ['roots', 'root'] }),
  fact('pl.stem', 'plants', 'Which part of a plant carries water up from the roots to the leaves?', 'the stem', ['the petals', 'the seeds', 'the flower'], 'The stem works like a bundle of tiny drinking straws, and holds the plant up towards the light.', { accept: ['stem', 'the trunk', 'trunk'] }),
  fact('pl.leaf', 'plants', 'Which part of a plant makes food using sunlight?', 'the leaves', ['the roots', 'the stem', 'the soil'], 'Leaves use sunlight, air and water to make the plant’s food. This is called photosynthesis.', { accept: ['leaves', 'leaf'] }),
  fact('pl.flower', 'plants', 'What is the main job of a flower?', 'to make seeds', ['to drink water', 'to hold the plant up', 'to make food from sunlight'], 'Flowers attract insects so they can be pollinated and make seeds.', C),
  mcq('pl.need', 'plants', 'What does a plant need to grow well?', [['Light, water, air and warmth', true], ['Only water, nothing else at all', false, 'Water alone isn’t enough: a plant in a dark cupboard goes pale and weak.'], ['Darkness and cold to rest in', false, 'Most plants need light and warmth.']], 'Plants need light, water, air, warmth, space and nutrients.'),
  mcq('pl.celery', 'plants', 'A stick of celery stands in blue water. After a day, the leaves have blue streaks. What does this show?', [['Water travels up the stem', true], ['Celery likes the colour blue', false, 'The colour is a clue to where the water went.'], ['The leaves were already blue', false, 'They turned blue because coloured water travelled up.']], 'The coloured water travelled up tiny tubes in the stem all the way to the leaves.'),
  mcq('pl.dark', 'plants', 'Two bean plants are watered the same. One is kept in a dark cupboard. What will it look like after two weeks?', [['Pale, yellowish and weak', true], ['Greener than the other one', false, 'Without light, it can’t make food, so it loses its green colour.'], ['Exactly the same', false, 'Light makes a big difference.']], 'Without light the plant can’t make its food, so it grows pale and spindly.'),
  fact('pl.nutrients', 'plants', 'What do plant roots take from the soil as well as water?', 'nutrients (minerals)', ['sunlight', 'tiny stones', 'sugar'], 'Minerals in the soil keep the plant healthy. That is why gardeners add compost.', C),
  mcq('pl.trunk', 'plants', 'A tree trunk is a very big, woody…', [['stem', true], ['root', false, 'The trunk is above ground, holding the tree up: a stem.'], ['leaf', false, 'Leaves grow on the branches.']], 'A trunk does the same job as a stem: it holds the tree up and carries water.'),
  fact('pl.photo', 'plants', 'What is it called when leaves make food using sunlight?', 'photosynthesis', ['pollination', 'germination', 'evaporation'], 'Photo means light. Leaves use light to make sugar for the plant.', C),

  // --- flowers, pollination and seeds
  order('sd.cycle', 'seeds', 'Put the life cycle of a flowering plant in order.', ['seed', 'germination (it sprouts)', 'young plant grows', 'flower is pollinated', 'new seeds form and are spread'], 'Seed, sprouting, growing, pollination, seeds again: a cycle.'),
  fact('sd.pollen', 'seeds', 'What powdery stuff do bees carry from flower to flower?', 'pollen', ['nectar', 'honey', 'sap'], 'Bees visit flowers for sweet nectar, and pollen sticks to their hairy bodies.', { accept: ['pollen grains'] }),
  fact('sd.pollination', 'seeds', 'What is it called when pollen moves from one flower to another?', 'pollination', ['photosynthesis', 'evaporation', 'hibernation'], 'After pollination, a flower can make seeds.', C),
  mcq('sd.bright', 'seeds', 'Why do many flowers have bright petals and a sweet smell?', [['To attract insects', true], ['To scare away hungry birds', false, 'Bright colours attract visitors.'], ['To keep the flower warm', false, 'Petals don’t keep the plant warm.']], 'Insects come for the nectar and carry pollen away with them.'),
  fact('sd.wind', 'seeds', 'Dandelion and sycamore seeds are spread by…', 'the wind', ['water', 'animals eating them', 'exploding pods'], 'Dandelion seeds have fluffy parachutes; sycamore seeds spin like helicopters.', C),
  fact('sd.animal', 'seeds', 'Blackberry seeds are spread when birds eat the berries. How do the seeds get to a new place?', 'they pass out in the bird’s droppings', ['the bird plants them with its beak', 'the wind blows the berries away', 'they float away down rivers'], 'The seeds survive the bird’s tummy and land far away, with a little fertiliser!', C),
  fact('sd.burr', 'seeds', 'Burdock seeds have tiny hooks. How are they spread?', 'they stick to animals’ fur', ['the wind blows them', 'they float on water', 'their pods explode'], 'The hooks catch on fur (and socks!) and drop off somewhere new. They gave the idea for Velcro.', C),
  fact('sd.coconut', 'seeds', 'How are coconuts spread?', 'they float on water', ['the wind', 'birds eat them', 'they stick to fur'], 'Coconuts can float across the sea to grow on another beach.', C),
  mcq('sd.why', 'seeds', 'Why is it good for seeds to travel away from the parent plant?', [['So they have room and light to grow', true], ['Because seeds like going on holiday', false, 'Ha! It is about having enough to grow.'], ['So the parent plant can rest', false, 'It is about giving the new plants room.']], 'If all the seeds fell in one spot, they would crowd each other out.'),
  fact('sd.germ', 'seeds', 'When a seed starts to sprout, it is called…', 'germination', ['pollination', 'dispersal', 'photosynthesis'], 'A seed needs water and warmth to germinate. Most seeds don’t need light until the leaves appear.', C),

  // --- nutrition
  fact('nu.carbs', 'nutrition', 'Bread, pasta, rice and potatoes are mainly which food group?', 'carbohydrates', ['protein', 'fats', 'vitamins'], 'Carbohydrates give us energy. Racing drivers and athletes eat lots of them.', { accept: ['carbohydrate', 'carbs', 'starchy foods'] }),
  fact('nu.protein', 'nutrition', 'Meat, fish, eggs, beans and nuts are rich in which food group?', 'protein', ['carbohydrates', 'fats', 'sugar'], 'Protein helps your body grow and repair muscles.', { accept: ['proteins'] }),
  mcq('nu.fruit', 'nutrition', 'Why should we eat plenty of fruit and vegetables?', [['They give us vitamins and fibre', true], ['They are the only food with energy', false, 'Lots of foods have energy; fruit and veg give vitamins and fibre.'], ['They make us grow taller overnight', false, 'Not overnight!']], 'Vitamins and minerals keep your body working well; fibre helps digestion.'),
  mcq('nu.fat', 'nutrition', 'Butter, oil and cheese contain fat. How much fat should we eat?', [['A small amount', true], ['None at all, ever', false, 'Our bodies do need a little fat.'], ['As much as we possibly can', false, 'Too much fat is unhealthy.']], 'A balanced diet has a little fat, and only a little sugar.'),
  mcq('nu.plants', 'nutrition', 'How is the way humans get food different from plants?', [['Plants make their own food', true], ['Humans make food from sunlight', false, 'Only plants can do that.'], ['There is no difference at all', false, 'Plants make food; animals must eat.']], 'Animals, including humans, can’t make their own food, so we eat plants or other animals.'),
  fact('nu.water', 'nutrition', 'What should you drink most of to stay healthy?', 'water', ['fizzy drinks', 'milkshakes', 'fruit squash'], 'Our bodies are more than half water. Sugary drinks are bad for teeth.'),
  mcq('nu.balanced', 'nutrition', 'Which is the most balanced lunch?', [['A chicken sandwich, an apple and water', true], ['Crisps, a chocolate bar and cola', false, 'Lots of fat and sugar, and no fruit or vegetables.'], ['A big bowl of sweets and juice', false, 'All sugar!']], 'Carbohydrate (bread), protein (chicken), fruit and water: balanced.'),
  mcq('nu.energy', 'nutrition', 'Turbo’s driver has a long race tomorrow. What should she eat tonight for slow-release energy?', [['Pasta with vegetables', true], ['A big bag of sweets', false, 'Sweets give a quick burst, then you feel tired.'], ['Nothing at all, to stay light', false, 'You need fuel for a long race!']], 'Starchy carbohydrates like pasta release energy slowly over a long time.'),

  // --- skeletons and muscles
  fact('sk.jobs', 'skeletons', 'Which of these is a job of your skeleton?', 'protecting your organs', ['digesting your food', 'pumping blood round', 'helping you see colours'], 'Your skeleton supports you, protects organs (your skull protects your brain) and helps you move.', C),
  fact('sk.skull', 'skeletons', 'Which bone protects your brain?', 'the skull', ['the ribs', 'the spine', 'the femur'], 'The skull is like a built-in crash helmet.', { accept: ['skull', 'cranium'] }),
  fact('sk.ribs', 'skeletons', 'Which bones protect your heart and lungs?', 'the ribs', ['the skull', 'the knee', 'the hip'], 'Your ribcage is like a cage around your heart and lungs.', { accept: ['ribs', 'ribcage', 'rib cage'] }),
  fact('sk.spine', 'skeletons', 'What is the long chain of bones down the middle of your back called?', 'the spine', ['the ribcage', 'the pelvis', 'the skull'], 'The spine is made of 33 small bones called vertebrae (some of them join together as you grow).', { accept: ['spine', 'backbone', 'the backbone', 'the spine'] }),
  fact('sk.femur', 'skeletons', 'Which is the longest bone in your body, in your thigh?', 'the femur', ['the skull', 'the rib', 'the spine'], 'The femur is also the strongest bone.', { accept: ['femur', 'thigh bone'] }),
  mcq('sk.muscle', 'skeletons', 'How do muscles move your bones?', [['They contract and pull on bones', true], ['They push the bones from inside', false, 'Muscles can only pull, not push.'], ['They melt and then set again', false, 'Muscles contract and relax.']], 'Muscles work in pairs: when one contracts and pulls, the other relaxes.'),
  mcq('sk.pairs', 'skeletons', 'When you bend your arm, the muscle at the front (biceps) contracts. What does the muscle at the back do?', [['It relaxes', true], ['It contracts too', false, 'If both pulled at once, your arm wouldn’t move.'], ['It disappears', false, 'It relaxes and gets longer.']], 'Muscles work in pairs: one pulls while the other relaxes. To straighten your arm, they swap.'),
  fact('sk.joint', 'skeletons', 'Where two bones meet, like at your knee or elbow, is called a…', 'joint', ['muscle', 'tendon', 'skull'], 'Joints let your skeleton bend.', { accept: ['a joint', 'joints'] }),
  mcq('sk.vertebrate', 'skeletons', 'An animal with a backbone is called a…', [['vertebrate', true], ['invertebrate', false, 'Invertebrates have NO backbone.'], ['carnivore', false, 'That is about what it eats.']], 'Fish, amphibians, reptiles, birds and mammals are vertebrates.'),
  mcq('sk.invert', 'skeletons', 'Which animal is an invertebrate (it has no backbone)?', [['a worm', true], ['a dog', false, 'Dogs have a backbone.'], ['a frog', false, 'Frogs have a backbone.']], 'Worms, snails, insects, spiders and jellyfish have no backbone.'),
  mcq('sk.exo', 'skeletons', 'Beetles have a hard skeleton on the OUTSIDE of their bodies. What is it called?', [['an exoskeleton', true], ['a shell suit', false, 'Close! Its proper name is an exoskeleton.'], ['a spine', false, 'Insects have no spine.']], 'Exo means outside. Crabs, beetles and ants have exoskeletons.'),

  // --- rocks and soils
  fact('rk.igneous', 'rocks', 'Rock that forms when hot melted rock (magma or lava) cools down is called…', 'igneous rock', ['sedimentary rock', 'metamorphic rock', 'plastic'], 'Igneous comes from the Latin word for fire. Granite and basalt are igneous.', C),
  fact('rk.sedimentary', 'rocks', 'Rock made from layers of sand, mud and shells squashed together over millions of years is called…', 'sedimentary rock', ['igneous rock', 'metamorphic rock', 'lava'], 'Sandstone, limestone and chalk are sedimentary. Fossils are found in them.', C),
  fact('rk.metamorphic', 'rocks', 'Rock that has been changed by great heat and pressure underground is called…', 'metamorphic rock', ['sedimentary rock', 'igneous rock', 'soil'], 'Metamorphic means changed shape. Marble was once limestone; slate was once mudstone.', C),
  mcq('rk.fossilrock', 'rocks', 'In which type of rock are you most likely to find a fossil?', [['sedimentary', true], ['igneous', false, 'Igneous rock was once melted: any fossil would be destroyed.'], ['metamorphic', false, 'Heat and pressure usually destroy fossils.']], 'Animals buried in mud and sand become fossils as the layers turn to sedimentary rock.'),
  mcq('rk.permeable', 'rocks', 'A rock that lets water soak into it is called…', [['permeable', true], ['impermeable', false, 'Impermeable rocks let no water in.'], ['magnetic', false, 'That is about magnets.']], 'Chalk and sandstone are permeable. Granite and slate are impermeable.'),
  mcq('rk.roof', 'rocks', 'Why is slate a good rock for roof tiles?', [['It splits into thin, waterproof sheets', true], ['It is soft and crumbly', false, 'Crumbly rock would fall apart in the rain.'], ['It soaks up the rain like a sponge', false, 'A roof must keep water OUT.']], 'Slate doesn’t let water through and splits into thin, flat pieces.'),
  order('rk.fossil', 'rocks', 'Put the steps of how a fossil forms in order.', ['an animal dies', 'it is buried by mud or sand', 'the soft parts rot away', 'over millions of years the layers turn to rock', 'the rock wears away and the fossil is found'], 'Death, burial, rotting, rock forms, discovery.'),
  fact('rk.soil', 'rocks', 'Soil is made from tiny pieces of rock mixed with…', 'dead plants and animals', ['bits of plastic and glass', 'melted metal from volcanoes', 'salt water from the sea'], 'Rotting leaves and dead creatures make soil rich, and worms mix it all up.', C),
  mcq('rk.hard', 'rocks', 'How could you test which of two rocks is harder?', [['Try scratching each one', true], ['Look carefully at their colour', false, 'Colour doesn’t tell you hardness.'], ['Smell them to see which is stronger', false, 'Smell doesn’t show hardness.']], 'A harder rock scratches less. Keep the test fair: use the same object and the same push.'),
  fact('rk.anning', 'rocks', 'Which fossil hunter from Lyme Regis found a famous ichthyosaur skeleton, the first to be properly recognised, when she was a girl?', 'Mary Anning', ['Mary Seacole', 'Marie Curie', 'Mary Rose'], 'Mary Anning was about 12 when her family found it, around 1811.', { accept: ['anning'] }),
  fact('rk.granite', 'rocks', 'Granite is a hard, speckled rock. Which family of rock is it?', 'igneous', ['sedimentary', 'metamorphic', 'fossil'], 'Granite forms when magma cools slowly underground.'),

  // --- light
  mcq('li.see', 'light', 'How do we see a book that is not a light source?', [['Light bounces off it into our eyes', true], ['Our eyes send out beams of light', false, 'Our eyes take light in; they don’t send it out.'], ['The book glows a little in the dark', false, 'Books don’t make their own light.']], 'Light from a source (like the Sun or a lamp) reflects off objects and into our eyes.'),
  fact('li.reflect', 'light', 'When light bounces off a surface, it is called…', 'reflection', ['shadow', 'refraction', 'absorption'], 'Mirrors and shiny surfaces reflect light very well.', { accept: ['reflecting', 'reflected'] }),
  mcq('li.shiny', 'light', 'Which surface reflects light best?', [['a shiny mirror', true], ['a black jumper', false, 'Dark, rough surfaces reflect very little light.'], ['a wooden table', false, 'Wood reflects some light, but a mirror reflects much more.']], 'Smooth, shiny surfaces reflect the most light.'),
  mcq('li.hivis', 'light', 'Why do cyclists wear reflective strips at night?', [['Headlights reflect off them', true], ['They make their own bright light', false, 'Reflective strips only shine when light hits them.'], ['They keep the cyclist warm at night', false, 'They are for being seen.']], 'Reflectors bounce car headlights straight back to the driver.'),
  mcq('li.closer', 'light', 'You hold a toy in front of a torch and move the torch CLOSER to the toy. What happens to the shadow?', [['It gets bigger', true], ['It gets smaller', false, 'Moving the light closer blocks more of the light, so the shadow grows.'], ['It disappears', false, 'There is still something blocking the light.']], 'The closer the light source, the bigger the shadow.'),
  mcq('li.opaque', 'light', 'Which material makes the darkest shadow?', [['an opaque material, like cardboard', true], ['a transparent material, like clear glass', false, 'Light passes straight through clear glass.'], ['a translucent material, like tissue paper', false, 'Tissue lets some light through, so its shadow is faint.']], 'Opaque materials block all light. Transparent ones let light through; translucent ones let some through.'),
  fact('li.transparent', 'light', 'A material you can see clearly through, like glass, is…', 'transparent', ['opaque', 'translucent', 'reflective'], 'Car windscreens must be transparent!', { accept: ['see-through'] }),
  mcq('li.sunglasses', 'light', 'Why should you wear sunglasses on very bright days?', [['To protect your eyes', true], ['To help you see in the dark', false, 'Sunglasses make things darker.'], ['To look like a racing driver', false, 'They might, but the real reason is protection.']], 'Sunlight contains invisible ultraviolet (UV) light that can damage eyes. Never look directly at the Sun.'),
  mcq('li.noon', 'light', 'Your shadow is shortest at about midday. Why?', [['The Sun is highest in the sky', true], ['The Sun is closest to the Earth at midday', false, 'It is about how HIGH the Sun is.'], ['You are taller at midday', false, 'You are the same height all day!']], 'When the Sun is high, light comes from above and makes a short shadow.'),
  mcq('li.straight', 'light', 'Light travels in…', [['straight lines', true], ['curly lines', false, 'Light doesn’t bend round corners: that is why shadows form.'], ['circles', false, 'Light goes straight.']], 'Because light travels in straight lines, an object blocking it makes a shadow behind.'),

  // --- forces and magnets
  mcq('fo.contact', 'forces', 'Which force does NOT need the objects to touch?', [['magnetism', true], ['friction', false, 'Friction needs two surfaces rubbing together.'], ['a push', false, 'A push needs contact.']], 'Magnetism (and gravity) act at a distance. Pushes, pulls and friction need contact.'),
  mcq('fo.friction', 'forces', 'Friction is a force that…', [['slows things down when they rub', true], ['makes things float on water', false, 'That is not friction.'], ['only happens out in space', false, 'Friction happens everywhere surfaces touch.']], 'Rough surfaces make more friction; smooth surfaces make less.'),
  mcq('fo.ramp', 'forces', 'Rosa rolls a toy car down a ramp onto three surfaces. On which will it travel furthest?', [['smooth wooden floor', true], ['thick carpet', false, 'Carpet is rough: lots of friction.'], ['grass', false, 'Grass is bumpy and has lots of friction.']], 'The smoothest surface has the least friction, so the car rolls furthest.'),
  mcq('fo.fair', 'forces', 'To make the ramp test fair, what must stay the same each time?', [['the car, the ramp height and the start', true], ['the surface the car rolls onto', false, 'The surface is the ONE thing you change. Everything else stays the same.'], ['nothing: change everything each time', false, 'Then you couldn’t tell what made the difference.']], 'Change one thing (the surface); keep everything else the same.'),
  mcq('fo.tyres', 'forces', 'Why do racing tyres need friction?', [['To grip the track', true], ['To make the car slower on purpose', false, 'Grip helps the car go round corners fast.'], ['To keep the tyres nice and clean', false, 'It is about grip.']], 'Without friction the tyres would spin, and the car would slide off at the corners.'),
  mcq('fo.useful', 'forces', 'When is friction USEFUL?', [['When you brake on a bike', true], ['When you push a heavy box across the floor', false, 'Here friction makes it harder.'], ['When a skier wants to go fast', false, 'Skiers wax their skis to REDUCE friction.']], 'Brakes work by friction. Without it, you couldn’t stop!'),
  fact('fo.attract', 'forces', 'Which material is attracted to a magnet?', 'iron', ['copper', 'aluminium', 'plastic'], 'Iron, steel, nickel and cobalt are magnetic. Most metals, like copper and aluminium, are not!', C),
  mcq('fo.coins', 'forces', 'Are ALL metals magnetic?', [['No: only some, like iron', true], ['Yes, every single metal is', false, 'Aluminium cans and copper pipes aren’t magnetic.'], ['No metals are magnetic at all', false, 'Iron and steel are.']], 'Recycling centres use big magnets to separate steel cans from aluminium ones.'),
  mcq('fo.poles', 'forces', 'You put the north pole of one magnet near the south pole of another. What happens?', [['They attract (pull together)', true], ['They repel (push apart)', false, 'Like poles repel; opposite poles attract.'], ['Nothing', false, 'Magnets always attract or repel each other.']], 'Opposite poles attract; like poles (N and N, or S and S) repel.'),
  mcq('fo.compass', 'forces', 'Why does a compass needle point north?', [['It is a magnet pulled by the Earth', true], ['It is very light and thin', false, 'Its lightness lets it turn, but magnetism points it.'], ['Someone sets it every morning', false, 'It points north by itself.']], 'The Earth acts like a giant magnet. A compass needle lines up with it.'),
  mcq('fo.gravity', 'forces', 'What force pulls things down towards the Earth?', [['gravity', true], ['friction', false, 'Friction slows things down; it doesn’t pull them down.'], ['magnetism', false, 'Gravity pulls everything, not just magnetic things.']], 'Gravity pulls everything towards the Earth. It keeps the Moon going round us too.'),

  // --- thinking like a scientist
  mcq('ws.fair', 'scientist', 'What is a fair test?', [['You change only one thing', true], ['A test where everybody wins', false, 'Fair here means the results can be trusted.'], ['A test you do once, very quickly', false, 'Good scientists repeat tests.']], 'Changing one thing at a time shows what really caused the difference.'),
  mcq('ws.predict', 'scientist', 'Before a test, Bleep says “I think the paper aeroplane with bigger wings will fly further.” What is this?', [['A prediction', true], ['A result', false, 'Results come AFTER the test.'], ['A conclusion', false, 'A conclusion is what you decide after looking at results.']], 'A prediction is what you think will happen, and why.'),
  mcq('ws.repeat', 'scientist', 'Why should you repeat a test a few times?', [['To check the results are reliable, not a fluke', true], ['Because the first time is always wrong', false, 'It isn’t always wrong, but one result could be a fluke.'], ['To make it take longer', false, 'Repeating makes results more trustworthy.']], 'If the results are similar each time, you can trust them more.'),
  mcq('ws.measure', 'scientist', 'Captain Nova is testing how far toy rockets fly. What is the best way to record it?', [['Measure it and write it in a table', true], ['Guess by looking at where it lands', false, 'Measuring is more accurate than guessing.'], ['Try to remember it in your head', false, 'Write results down so you don’t forget.']], 'Scientists measure carefully and record results in tables and charts.'),
  mcq('ws.conclusion', 'scientist', 'The results show that cars always roll further on wood than carpet. What is a good conclusion?', [['Smoother surfaces have less friction', true], ['Carpet is bad for toy cars', false, 'A conclusion should explain the pattern.'], ['The car got tired on the carpet', false, 'Cars don’t get tired!']], 'A conclusion explains what the results show, and why.'),
  mcq('ws.variable', 'scientist', 'In a test of which plant food makes beans grow tallest, what should you MEASURE?', [['the height of each bean plant', true], ['the colour of the pots', false, 'Pot colour isn’t what you’re testing.'], ['how many people watch', false, 'That doesn’t tell you about growth.']], 'You change the plant food, measure the height and keep everything else the same.'),

  // --- Europe
  ...EUROPE.map(([id, name, explain, accept]) => mapfact(`eu.${id.toLowerCase()}`, 'europe', 'europe', 'countries', id, name, explain, { choosePrompt: 'Which country is highlighted?', accept })),
  ...CAPITALS.map(([country, capital, wrongs]) => fact(`eucap.${capital.toLowerCase()}`, 'europe', `What is the capital city of ${country}?`, capital, wrongs, `${capital} is the capital of ${country}.`, { accept: [capital.toLowerCase()] })),
  fact('eu.biggest', 'europe', 'Which mountain range stretches across Switzerland, Austria, France and Italy?', 'the Alps', ['the Pennines', 'the Himalayas', 'the Andes'], 'The Alps are the biggest mountain range entirely in Europe. Mont Blanc is its highest peak.', { accept: ['alps'] }),
  fact('eu.tunnel', 'europe', 'What links England and France under the sea?', 'the Channel Tunnel', ['the Severn Bridge', 'Hadrian’s Wall', 'the Forth Bridge'], 'Trains travel through it under the English Channel. It opened in 1994.', C),

  // --- UK cities, rivers and mountains
  ...CITIES.map(([id, name, explain]) => mapfact(`city.${id}`, 'ukplaces', 'uk', 'markers', id, name, explain, { choosePrompt: 'Which city is marked?', group: 'city', accept: id === 'newcastle' ? ['Newcastle'] : [] })),
  ...RIVERS.map(([id, name, explain]) => mapfact(`riv.${id}`, 'ukplaces', 'uk', 'rivers', `river-${id}`, name, explain, { choosePrompt: 'Which river is highlighted?', accept: [name.replace('River ', '')], group: 'river' })),
  ...PEAKS.map(([id, name, explain, accept]) => mapfact(`peak.${id}`, 'ukplaces', 'uk', 'markers', id, name, explain, { choosePrompt: 'Which mountain is marked?', group: 'peak', accept })),
  fact('uk.highest', 'ukplaces', 'What is the highest mountain in the UK?', 'Ben Nevis', ['Scafell Pike', 'Snowdon', 'Slieve Donard'], 'Ben Nevis is 1,345 metres high, in the Scottish Highlands.', { accept: ['ben nevis'] }),
  fact('uk.longest', 'ukplaces', 'What is the longest river in the UK?', 'the River Severn', ['the River Thames', 'the River Tay', 'the River Wye'], 'The Severn starts in the mountains of Wales and flows into the Bristol Channel. The Thames is second.', { accept: ['severn', 'river severn'] }),

  // --- volcanoes and earthquakes
  fact('vo.crust', 'volcanoes', 'What is the thin, rocky outer layer of the Earth called?', 'the crust', ['the core', 'the mantle', 'the atmosphere'], 'The crust is broken into huge pieces called tectonic plates.', { accept: ['crust'] }),
  order('vo.layers', 'volcanoes', 'Put the layers of the Earth in order, from the outside to the middle.', ['crust', 'mantle', 'outer core', 'inner core'], 'Like a peach: thin skin (crust), thick flesh (mantle), and a stone in the middle (core).'),
  fact('vo.plates', 'volcanoes', 'The Earth’s crust is cracked into giant pieces. What are they called?', 'tectonic plates', ['crust tiles', 'fault blocks', 'continents'], 'The plates move very slowly, about as fast as your fingernails grow.', C),
  mcq('vo.quake', 'volcanoes', 'What causes most earthquakes?', [['Plates slipping past each other', true], ['Very heavy lorries on the roads', false, 'Lorries can shake the ground a little, but real earthquakes come from moving plates.'], ['Big thunderstorms overhead', false, 'Storms are in the air, not underground.']], 'Plates get stuck, pressure builds up, then they slip suddenly and the ground shakes.'),
  mcq('vo.where', 'volcanoes', 'Where are most volcanoes found?', [['Along the edges of tectonic plates', true], ['In the middle of every country', false, 'They cluster where plates meet.'], ['Only at the North Pole', false, 'There are volcanoes all over the world, mostly at plate edges.']], 'The “Ring of Fire” around the Pacific Ocean has hundreds of volcanoes.'),
  fact('vo.ring', 'volcanoes', 'The ring of volcanoes and earthquakes around the Pacific Ocean is called the…', 'Ring of Fire', ['Circle of Smoke', 'Lava Loop', 'Great Wall'], 'It stretches past Japan, New Zealand, the west coast of America and Chile.', C),
  fact('vo.etna', 'volcanoes', 'Which active volcano is on the island of Sicily, in Italy?', 'Mount Etna', ['Ben Nevis', 'Mount Everest', 'Mount Snowdon'], 'Etna is one of the most active volcanoes in the world.', C),
  mcq('vo.types', 'volcanoes', 'A volcano that has not erupted for thousands of years but might again is…', [['dormant', true], ['active', false, 'Active volcanoes erupt often, or have erupted recently.'], ['extinct', false, 'Extinct volcanoes are not expected to erupt ever again.']], 'Active: erupts often. Dormant: sleeping. Extinct: finished for good. Edinburgh Castle stands on an extinct volcano!'),
  mcq('vo.safe', 'volcanoes', 'What should you do during an earthquake if you are indoors?', [['Get under a strong table', true], ['Run outside past the windows', false, 'Glass and falling things are dangerous. Stay under cover.'], ['Stand in the middle of the room', false, 'Get under something strong.']], '“Drop, cover and hold on” protects you from falling objects.'),
  fact('vo.iceland', 'volcanoes', 'Which European island country has many volcanoes and uses their heat to warm homes?', 'Iceland', ['Ireland', 'Italy', 'Malta'], 'Iceland sits on the edge of two plates. Hot water from underground heats houses.', { accept: ['iceland'] }),

  // --- compass and grid references
  mcq('cp.ne', 'compass', 'What direction is halfway between north and east?', [['north-east', true], ['south-east', false, 'South-east is between south and east.'], ['north-west', false, 'North-west is between north and west.']], 'The 8 points: N, NE, E, SE, S, SW, W, NW.'),
  mcq('cp.sw', 'compass', 'What direction is opposite north-east?', [['south-west', true], ['south-east', false, 'Opposite north is south, and opposite east is west: south-west.'], ['north-west', false, 'Turn right round: north-east → south-west.']], 'Opposite N is S; opposite E is W. So opposite NE is SW.'),
  order('cp.order', 'compass', 'Put these directions in order, going clockwise from north.', ['north', 'north-east', 'east', 'south-east', 'south'], 'Clockwise: N, NE, E, SE, S, SW, W, NW.'),
  mcq('cp.grid', 'compass', 'On a map grid with letters along the bottom and numbers up the side, how do you read grid reference C4?', [['Go along to column C, then up to row 4', true], ['Go up to 4, then along to C, in any order', false, 'Always go along first: “along the corridor, then up the stairs”.'], ['Count 4 squares from the top', false, 'Rows are usually counted up from the bottom.']], 'Along the corridor (letters), then up the stairs (numbers).'),
  mcq('cp.turn', 'compass', 'Bleep the robot faces north and turns 90° clockwise. Then it turns 45° more clockwise. Which way is Bleep facing?', [['south-east', true], ['east', false, 'That is after the first turn. 45° more goes to south-east.'], ['north-east', false, 'North-east is only 45° from north.']], 'North → east is 90°. Another 45° clockwise reaches south-east.'),
  mcq('cp.sun', 'compass', 'In the UK, the Sun rises roughly in the…', [['east', true], ['west', false, 'The Sun SETS in the west.'], ['north', false, 'In the UK, the Sun is never in the north at midday.']], 'The Sun rises in the east and sets in the west.'),
  mcq('cp.key', 'compass', 'What does the key on a map tell you?', [['What the symbols mean', true], ['How to unlock the map', false, 'It is a different kind of key!'], ['Which way is north', false, 'That is the compass or north arrow.']], 'A key (or legend) explains the symbols: a blue line is a river, a cross might be a church.'),
  mcq('cp.scale', 'compass', 'On a map, 1 cm stands for 1 km. Two towns are 5 cm apart on the map. How far apart are they really?', [['5 km', true], ['5 cm', false, 'That is the distance on paper. Each centimetre stands for a kilometre.'], ['1 km', false, 'Each cm is 1 km, so 5 cm is 5 km.']], 'The scale tells you how map distances match real distances.'),

  // --- climate and biomes
  mcq('cl.weather', 'climate', 'What is the difference between weather and climate?', [['Weather is daily; climate is long-term', true], ['They mean exactly the same thing', false, 'Weather changes daily. Climate is the long-term pattern.'], ['Climate only happens in hot places', false, 'Every place has a climate.']], 'Today’s rain is weather. “The UK is mild and wet” is climate.'),
  fact('cl.uk', 'climate', 'The UK has mild summers and cool, wet winters. What kind of climate is this?', 'temperate', ['tropical', 'polar', 'desert'], 'Temperate climates are not too hot and not too cold.', { accept: ['temperate climate'] }),
  fact('cl.tropical', 'climate', 'Hot, wet places near the Equator have which climate?', 'tropical', ['polar', 'temperate', 'Mediterranean'], 'Rainforests grow in tropical climates.', { accept: ['tropical climate'] }),
  fact('cl.polar', 'climate', 'The very cold climates near the North and South Poles are called…', 'polar', ['tropical', 'desert', 'temperate'], 'Polar regions have long, dark winters and freezing temperatures.', { accept: ['polar climate'] }),
  mcq('cl.biome', 'climate', 'A large area with its own climate, plants and animals, like a desert or a rainforest, is called a…', [['biome', true], ['continent', false, 'A continent is a big area of land; it can contain many biomes.'], ['country', false, 'Biomes cross country borders.']], 'Biomes include rainforest, desert, grassland, tundra and ocean.'),
  mcq('cl.savanna', 'climate', 'Lions, zebras and giraffes live on hot grasslands in Africa. What is this biome called?', [['savanna', true], ['tundra', false, 'Tundra is cold and treeless, near the Arctic.'], ['rainforest', false, 'Rainforests are thick forests, not open grasslands.']], 'Savannas are hot grasslands with a wet season and a dry season.'),
  mcq('cl.tundra', 'climate', 'Which biome is cold, treeless and has frozen ground for most of the year?', [['tundra', true], ['desert', false, 'Hot deserts are dry, but not frozen.'], ['rainforest', false, 'Rainforests are hot and wet.']], 'The tundra is near the Arctic. Reindeer and Arctic foxes live there.'),
  mcq('cl.antarctic', 'climate', 'Antarctica gets very little rain or snow. Which word describes it?', [['a cold desert', true], ['a rainforest', false, 'It is far too cold and dry.'], ['a temperate grassland', false, 'It is covered in ice.']], 'A desert is any place with very little rain. Antarctica is the biggest desert on Earth!'),

  // --- states of matter (stretch)
  mcq('st.solid', 'states', 'Which of these is a solid?', [['a brick', true], ['orange juice', false, 'Juice is a liquid: it flows.'], ['steam', false, 'Steam is a gas.']], 'Solids keep their shape. Liquids flow. Gases spread out to fill any space.'),
  mcq('st.liquid', 'states', 'What is special about a liquid?', [['It flows and takes the shape of its container', true], ['It keeps its own shape', false, 'That is a solid.'], ['It spreads out to fill a whole room', false, 'That is a gas.']], 'Pour water into a jug, then a bowl: it takes each shape.'),
  fact('st.melt', 'states', 'When a solid turns into a liquid, like ice turning into water, it is called…', 'melting', ['freezing', 'evaporating', 'condensing'], 'Heating makes solids melt. Chocolate melts in your hand!', { accept: ['melt', 'melts'] }),
  fact('st.freeze', 'states', 'What temperature does water freeze at?', '0 °C', ['100 °C', '10 °C', '50 °C'], 'Water freezes into ice at 0 °C and boils at 100 °C.', C),
  fact('st.evap', 'states', 'When water turns into water vapour (a gas), it is called…', 'evaporation', ['condensation', 'freezing', 'melting'], 'Puddles disappear on sunny days because the water evaporates.', { accept: ['evaporating', 'evaporate'] }),
  fact('st.condense', 'states', 'When water vapour cools and turns back into liquid water, like on a cold window, it is called…', 'condensation', ['evaporation', 'melting', 'freezing'], 'The droplets on the bathroom mirror after a bath are condensation.', { accept: ['condensing', 'condense'] }),
  order('st.cycle', 'states', 'Put the water cycle in order, starting with the sea.', ['water evaporates from the sea', 'water vapour rises and cools', 'it condenses into clouds', 'rain falls (precipitation)', 'rivers carry water back to the sea'], 'Evaporation, condensation, precipitation, collection: round and round.'),
  mcq('st.gas', 'states', 'Which of these is a gas?', [['the air we breathe', true], ['a glass of milk', false, 'Milk is a liquid.'], ['a pile of sand', false, 'Each grain of sand is a solid.']], 'Air is a mixture of gases. You can’t see it, but you can feel wind.'),

  // --- digestion and teeth (stretch)
  fact('dg.incisor', 'digestion', 'Which teeth at the front of your mouth are for biting and cutting?', 'incisors', ['molars', 'canines', 'wisdom teeth'], 'Incisors are flat and sharp, like little chisels.', { accept: ['incisor'] }),
  fact('dg.canine', 'digestion', 'Which pointed teeth are for tearing food?', 'canines', ['incisors', 'molars', 'premolars'], 'Canine means dog-like. Meat-eaters like wolves have big canines.', { accept: ['canine'] }),
  fact('dg.molar', 'digestion', 'Which big, flat teeth at the back are for grinding and chewing?', 'molars', ['canines', 'incisors', 'fangs'], 'Molars crush food. Plant-eaters like cows have lots of big molars.', { accept: ['molar'] }),
  order('dg.journey', 'digestion', 'Put the journey of food through the body in order.', ['mouth', 'oesophagus (food pipe)', 'stomach', 'small intestine', 'large intestine'], 'Mouth, food pipe, stomach, small intestine (nutrients absorbed), large intestine (water absorbed).'),
  mcq('dg.stomach', 'digestion', 'What happens to food in the stomach?', [['It is churned up with acid', true], ['It turns straight into blood', false, 'Food is broken down step by step first.'], ['Nothing: it just sits and waits', false, 'The stomach is busy churning and mixing.']], 'Stomach acid and churning muscles turn food into a soupy mush.'),
  mcq('dg.small', 'digestion', 'Where do most nutrients pass from food into the blood?', [['the small intestine', true], ['the mouth and tongue', false, 'Digestion starts in the mouth, but nutrients are absorbed later.'], ['the front teeth', false, 'Teeth break food up.']], 'The small intestine is about 6 metres long, with a huge surface for absorbing nutrients.'),
  mcq('dg.brush', 'digestion', 'Why should you brush your teeth twice a day?', [['To stop tooth decay', true], ['To make them grow faster', false, 'Brushing keeps them healthy, not bigger.'], ['To make them whiter than snow', false, 'The main reason is stopping decay.']], 'Bacteria in plaque turn sugar into acid that rots teeth.'),
  fact('dg.saliva', 'digestion', 'What liquid in your mouth starts to break food down and makes it easier to swallow?', 'saliva', ['blood', 'stomach acid', 'water'], 'Saliva (spit) softens food and starts digesting starch.', { accept: ['spit'] }),

  // --- classification keys (stretch)
  mcq('ky.what', 'keys', 'What is a classification key?', [['Yes/no questions to name a living thing', true], ['A special key that opens a zoo', false, 'It is a different kind of key!'], ['A list of animals from A to Z', false, 'A key uses questions, not the alphabet.']], 'Each question splits the group in two until only one answer is left.'),
  mcq('ky.legs', 'keys', 'A key asks: “Does it have 6 legs?” Which animal goes down the YES branch?', [['a ladybird', true], ['a spider', false, 'Spiders have 8 legs.'], ['a snail', false, 'Snails have no legs.']], 'Insects have 6 legs. Ladybirds are insects.'),
  mcq('ky.good', 'keys', 'Which is a good question for a key?', [['Does it have feathers?', true], ['Is it nice?', false, 'People would disagree! Key questions need clear yes/no answers.'], ['Is it my favourite?', false, 'That depends on who answers.']], 'Good key questions are about features everyone can check.'),
  mcq('ky.split', 'keys', 'You want to separate a fish, a bird, a dog and a snake. Which first question splits them into two groups of two?', [['Does it have legs?', true], ['Does it have a backbone?', false, 'All four have backbones, so that doesn’t split them.'], ['Is it alive?', false, 'They are all alive.']], 'Legs: bird and dog. No legs: fish and snake. Then ask another question for each pair.'),
  mcq('ky.vert', 'keys', 'A key asks: “Does it have a backbone?” Which goes down the NO branch?', [['a jellyfish', true], ['a shark', false, 'Sharks are fish, with a backbone (made of cartilage).'], ['a penguin', false, 'Penguins are birds: they have a backbone.']], 'Jellyfish are invertebrates.'),
  mcq('ky.flower', 'keys', 'Plants can be sorted into flowering plants and non-flowering plants. Which is a non-flowering plant?', [['a fern', true], ['a daisy', false, 'Daisies flower.'], ['an apple tree', false, 'Apple trees have blossom.']], 'Ferns and mosses make spores instead of seeds.'),

  // --- circuits (stretch)
  mcq('ci.brighter', 'circuits', 'What happens if you add a second battery to a circuit with one bulb?', [['The bulb gets brighter', true], ['The bulb gets dimmer', false, 'More batteries push more electricity: brighter.'], ['Nothing changes', false, 'The extra battery makes a difference.']], 'More batteries (cells) make a bulb brighter, or a motor faster.'),
  mcq('ci.dimmer', 'circuits', 'What happens if you add a second bulb in a loop with one battery?', [['Both bulbs are dimmer', true], ['Both are brighter', false, 'They share the battery’s push, so each is dimmer.'], ['Only one lights', false, 'Both light, but dimly.']], 'The bulbs share the electricity from the battery.'),
  mcq('ci.insulator', 'circuits', 'Why are electric wires covered in plastic?', [['Plastic is an insulator', true], ['To make them colourful', false, 'The colours help electricians, but plastic is for safety.'], ['Plastic is a good conductor', false, 'Plastic does NOT conduct electricity.']], 'Copper inside conducts electricity; plastic outside insulates.'),
  mcq('ci.test', 'circuits', 'You put a spoon in the gap of a circuit and the bulb lights. What does that tell you?', [['The spoon is a conductor', true], ['The spoon is an insulator', false, 'Insulators would leave the bulb off.'], ['The bulb in the circuit is broken', false, 'It lit, so it works!']], 'Testing materials in a circuit gap shows conductors and insulators.'),
  fact('ci.symbol', 'circuits', 'In a circuit, what does a cell (battery) provide?', 'the push that makes electricity flow', ['the light from the bulb', 'a gap in the wires', 'friction to slow it down'], 'The cell pushes electricity round the circuit.', C),
  mcq('ci.motor', 'circuits', 'Turbo’s team builds a toy car with a motor and a battery. How could they make it go faster?', [['Add another battery', true], ['Add another bulb in the circuit', false, 'That would share the electricity and slow the motor.'], ['Paint it red', false, 'Red is fast-looking, but it doesn’t change the circuit!']], 'More cells give the motor more push.'),
];

export default [{ subject: 'science', deck: 'y3', topics, items }];
